sp_widget.client_script:
api.controller = function($location) {
  var c = this;

  c.goToRecordList = function() {
    $location.search('id', 'bf_record_list');
  };
};

sp_widget.css:
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
  flex-shrink: 0;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon {
  margin-right: 8px;
  color: $brand-primary;
  font-size: 16px;
}
.sp-card-body {
  padding: 24px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}
.sp-about-text {
  font-size: $font-size-base;
  color: $text-color;
  line-height: 1.6;
  margin-bottom: 16px;
}
.sp-about-features {
  list-style: none;
  padding: 0;
  margin: 0 0 24px 0;
  li {
    padding: 6px 0;
    font-size: $font-size-base;
    color: $text-secondary;
  }
}
.sp-feature-check {
  color: $brand-success;
  margin-right: 8px;
  font-size: 12px;
}
.sp-btn-group {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: auto;
  flex-wrap: wrap;
}
.sp-btn-primary {
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, box-shadow 0.15s;
  cursor: pointer;
  border: none;
  background: $brand-primary;
  color: $btn-primary-color;
  &:hover:not(:disabled) {
    background: $brand-primary-dark;
    box-shadow: 0 2px 8px rgba($brand-primary, 0.3);
    color: $btn-primary-color;
  }
}
.sp-btn-secondary {
  background: $background-primary;
  border: 1px solid $border-tertiary;
  color: $text-color;
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  &:hover {
    background: $background-secondary;
  }
}
